"""Islamiat (Ikhtiari) XII PDF98: pp.186–187 — Chapter 4 opening: concept of Islamic government (Bani Isra'il 80). Run: python class12_iski_page098.py"""
from class12_iski_common import BOOK, Builder, rec, P, L, AR


def p98():
    b = Builder()
    b.h('Chapter Four: The Islamic system of government and state', 'بابِ چہارم: اسلام کا نظامِ حکومت و ریاست', 'څلورم څپرکی: د اسلام د حکومت او دولت نظام')
    b.h('Teaching objectives', 'تدریسی مقاصد', 'تدریسي موخې')
    b.p('The purpose of this lesson is to enable the students that they:', 'اس سبق کا مقصد طلبہ اور طالبات کو اس قابل بنانا ہے کہ وہ:', 'د دې لوست موخه دا ده چې زده‌کوونکي دې ته وړ کړي چې:')
    L(b, [('• can know the beginning and development of Islamic civilisation and culture and its importance in the present age, and get the motivation to play their role in it.', '• اسلامی تہذیب و تمدن کی ابتداء، ارتقاء اور عصرِ حاضر میں اس کی اہمیت جان سکیں اور اس میں اپنا کردار ادا کرنے کی تحریک پا سکیں۔', '• د اسلامي تهذیب او تمدن پیل، وده او په اوسني عصر کې یې اهمیت وپېژني، او په کې د خپل رول د لوبولو هڅونه ومومي.'),
          ('• as citizens of an Islamic state, students can know their rights and duties.', '• طلبہ ایک اسلامی ریاست کے شہری ہونے کی حیثیت سے اپنے حقوق و فرائض کو جان سکیں۔', '• زده‌کوونکي د یوه اسلامي دولت د اتباعو په توګه خپل حقونه او دندې وپېژني.'),
          ('• can compare the concept of state and style of government given by Islam with the present age.', '• اسلام کا دیا ہوا تصورِ ریاست و طرزِ حکومت کا دورِ حاضر سے موازنہ کر سکیں۔', '• د اسلام ورکړی د دولت تصور او د حکومت طرز له اوسنۍ دورې سره پرتله کړای شي.')])
    b.h('1. The concept of the Islamic system of government', '۱۔ اسلامی نظامِ حکومت کا تصور', '۱. د اسلامي حکومت د نظام تصور')
    b.p('The very spirit of Islamic teachings is that the sovereignty of Allah be established on Allah\'s earth. This matter is not possible until the collective power of any society becomes subject to Islam. All the noble prophets (peace be upon them) kept struggling for this very thing, that power remain subject to the will and intention of Allah the Exalted. This matter can be estimated also from the following noble verse, in which Allah the Exalted taught this supplication to the Noble Prophet ﷺ.', 'اسلامی تعلیمات کی روح یہی ہے کہ اللہ کی زمین پر اللہ کی حاکمیت قائم ہو جائے۔ یہ بات اس وقت تک ممکن نہیں جب تک کسی بھی معاشرے کی اجتماعی قوت اسلام کے تابع نہ ہو جائے۔ تمام انبیائے کرام علیہم السلام یہی جدوجہد کرتے رہے کہ اقتدار اللہ تعالیٰ کی مرضی و منشا کے تابع رہے۔ اس بات کا اندازہ درج ذیل آیتِ کریمہ سے بھی لگایا جا سکتا ہے۔ جس میں اللہ تعالیٰ نے نبی کریم صلی اللہ علیہ وآلہٖ وسلم کو یہ دعا سکھائی۔', 'د اسلامي لارښوونو روح همدا دی چې د الله پر ځمکه د الله حاکمیت جوړ شي. دا خبره تر هغو ممکنه نه ده چې د هرې ټولنې ټولیز ځواک د اسلام تابع نشي. ټولو انبیاء کرامو علیهم السلام همدا هڅه کوله چې واک د الله تعالی د خوښې او ارادې تابع پاتې شي. د دې خبرې اټکل له لاندې کریمه آیت هم کېدای شي، چې په کې الله تعالی نبي کریم ﷺ ته دا دعا وښوده.')
    AR(b, 'وَقُلْ رَّبِّ اَدْخِلْنِيْ مُدْخَلَ صِدْقٍ وَّاَخْرِجْنِيْ مُخْرَجَ صِدْقٍ وَّاجْعَلْ لِّيْ مِنْ لَّدُنْكَ سُلْطٰنًا نَّصِيْرًا', 'بنی اسرائیل: 80')
    b.p('Translation: And say: O Lord, cause me to enter well (into Madinah), and bring me out well (from Makkah), and make strength and power from Your presence my helper.', 'ترجمہ: اور کہو کہ اے پروردگار مجھے (مدینے) میں اچھی طرح داخل کیجیے اور (مکے) سے اچھی طرح نکالیو۔ اور اپنے ہاں سے زور اور قوت کو میرا مددگار بنائیو۔', 'ژباړه: او ووایه: اې ربه، ما (مدینې ته) په ښه ډول ننباسه، او (له مکې) مې په ښه ډول وباسه، او له خپل لوري زور او ځواک زما مرستندوی وګرځوه.')
    r1 = rec(b, 4, 186, 98, [186], first=True)
    t = Builder()
    P(t, [('In this noble verse the importance of the formation of the state is evident like broad daylight. By it this very thing is meant: that O Allah, either grant me power, or grant me such a status in which some government becomes my helper, so that I can fulfil the obligation of enjoining good and forbidding evil in the correct sense.', 'اس آیتِ کریمہ میں ریاست کی تشکیل کی اہمیت روزِ روشن کی طرح عیاں ہے۔ اس سے مراد یہی ہے کہ اے اللہ تعالیٰ یا تو مجھے اقتدار عطا کر یا مجھے ایسی حیثیت عطا فرما جس میں کوئی حکومت میری مددگار بن جائے تاکہ میں امر بالمعروف اور نہی عن المنکر کا فریضہ صحیح معنوں میں ادا کر سکوں۔', 'په دې کریمه آیت کې د دولت د جوړښت اهمیت د روښانه ورځې په څېر څرګند دی. مراد یې همدا دی: اې الله تعالی، یا ماته واک راکړه، یا ماته داسې حیثیت راکړه چې کوم حکومت زما مرستندوی شي، تر څو د امر بالمعروف او نهي عن المنکر فریضه په سمه مانا ادا کړم.'),
          ('From this hadith of Kanz al-\'Ummal too this matter becomes clear, in which the Noble Prophet ﷺ said:', 'کنز العمال کی اس حدیث سے بھی یہ بات واضح ہو جاتی ہے کہ جس میں نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے فرمایا', 'د کنز العمال له دې حدیث هم دا خبره روښانه کېږي چې په کې نبي کریم ﷺ وفرمایل:'),
          ('Translation: Islam and government and state are twin brothers. Neither of the two can be correct without the other. So the example of Islam is like that of a building, and government is, as it were, its guardian. The building which has no foundation falls, and that which has no guardian is looted. (Kanz al-\'Ummal)', 'ترجمہ: اسلام اور حکومت و ریاست دو جڑواں بھائی ہیں۔ دونوں میں سے کوئی ایک دوسرے کے بغیر درست نہیں ہو سکتا۔ پس اسلام کی مثال ایک عمارت کی سی ہے اور حکومت گویا اس کی نگہبان ہے جس عمارت کی بنیاد نہ ہو وہ گر جاتی ہے اور جس کا نگہبان نہ ہو وہ لوٹ لی جاتی ہے۔ (کنز العمال)', 'ژباړه: اسلام او حکومت او دولت دوه غبرګوني وروڼه دي. له دواړو هېڅ یو له بل پرته سم نشي کېدای. نو د اسلام مثال د یوې ودانۍ په څېر دی، او حکومت ګواکې د هغې ساتونکی دی. هغه ودانۍ چې بنسټ ونه لري، ړنګېږي؛ او هغه چې ساتونکی ونه لري، لوټل کېږي. (کنز العمال)'),
          ('The style and practical wisdom with which the Noble Prophet ﷺ, after the announcement of prophethood, began the invitation to the truth — its purpose and aim was this very thing, that the worship and obedience of other than Allah end forever; the system of life as a whole become subject to the divine commands; social customs and traditions and the traditional system of worship be ended and human greatness and dignity be increased. For the attainment of this purpose he ﷺ bore countless hardships and pains, and ultimately was also compelled to migrate. After coming to Madinah, through the Covenant of Madinah he ﷺ laid the foundation of such a state in which, in a span of only ten years, the establishment of the Islamic government came into practice. This was the miracle of Quranic teachings, that he ﷺ did not keep any distinction between religion and state, and made the collective life of Muslims subject to the law of Allah. He ﷺ, presenting a beautiful blend of religion and state and government, established such an example in which there was nothing but welfare.', 'نبی اکرم صلی اللہ علیہ وآلہٖ وسلم نے اعلانِ نبوت کے بعد جس انداز اور حکمتِ عملی سے دعوتِ حق کا آغاز کیا اس کا مقصود و مطلوب یہی تھا کہ غیر اللہ کی عبادت و اطاعت ہمیشہ ہمیشہ کے لیے ختم ہو جائے۔ نظامِ زندگی مجموعی طور پر احکاماتِ الٰہی کے تابع ہو جائے۔ معاشرتی رسم و رواج اور روایتی نظامِ عبادات کو ختم کر کے انسانی عظمت و وقار میں اضافہ ہو جائے۔ اس مقصد کے حصول کے لیے آپ صلی اللہ علیہ وآلہٖ وسلم نے بے شمار مصائب و آلام برداشت کیے اور بالآخر ہجرت کرنے پر بھی مجبور ہو گئے۔ آمدِ مدینہ کے بعد آپ صلی اللہ علیہ وآلہٖ وسلم نے میثاقِ مدینہ کے ذریعے ایک ایسی ریاست کی بنیاد رکھ دی جس پر صرف دس سال کے عرصہ میں اسلامی حکومت کا قیام عمل میں آ گیا۔ یہ قرآنی تعلیمات کا اعجاز تھا کہ آپ صلی اللہ علیہ وآلہٖ وسلم نے دین و ریاست میں امتیاز روا نہ رکھا اور مسلمانوں کی اجتماعی زندگی کو اللہ کے قانون کے تابع کر دیا۔ آپ صلی اللہ علیہ وآلہٖ وسلم نے دین اور ریاست و حکومت کا حسین امتزاج پیش کر کے ایسی مثال قائم فرما دی کہ جس میں فلاح ہی فلاح تھی۔', 'نبي اکرم ﷺ د نبوت له اعلان وروسته په کوم انداز او عملي حکمت د حق بلنه پیل کړه، د هغې موخه همدا وه چې د غیرالله عبادت او اطاعت د تل لپاره ختم شي؛ د ژوند نظام په ټولیز ډول د الهي احکامو تابع شي؛ ټولنیز دودونه او دودیز عبادي نظام ختم شي او انساني عظمت او وقار زیات شي. د دې موخې د ترلاسه کولو لپاره هغه ﷺ بې‌شمېره مصیبتونه او دردونه وزغمل، او بالاخره هجرت ته هم مجبور شو. مدینې ته له راتګ وروسته هغه ﷺ د میثاق مدینه له لارې د داسې دولت بنسټ کېښود چې یوازې په لسو کلونو کې پرې د اسلامي حکومت جوړښت عملي شو. دا د قرآني لارښوونو معجزه وه چې هغه ﷺ د دین او دولت ترمنځ توپیر ونه ساته، او د مسلمانانو ټولیز ژوند یې د الله د قانون تابع کړ. هغه ﷺ د دین او دولت او حکومت ښکلې ګډه وړاندې کړه او داسې بېلګه یې جوړه کړه چې په کې یوازې هوساینه وه.'),
          ('In fact the Islamic system of government presents such a concept of government in which the following qualities are present.', 'دراصل اسلامی نظامِ حکومت کا ایسا تصور پیش کرتا ہے، جس میں درج ذیل اوصاف موجود ہوں۔', 'په اصل کې اسلام د حکومت داسې تصور وړاندې کوي چې په کې لاندې صفتونه وي.')])
    L(t, [('a. The divine commands should prevail over all false religions.', 'ا۔ احکاماتِ ربانی کو تمام ادیانِ باطلہ پر غلبہ حاصل رہے۔', 'الف. الهي احکام دې پر ټولو باطلو دینونو غالب وي.'),
          ('b. A strong system of enjoining good and forbidding evil should be established.', 'ب۔ امر بالمعروف اور نہی عن المنکر کا مضبوط نظام قائم ہو۔', 'ب. د امر بالمعروف او نهي عن المنکر قوي نظام دې جوړ وي.'),
          ('c. Worldly affairs should practically be linked with success in the Hereafter.', 'ج۔ دنیاوی امور عملی طور پر اخروی فلاح سے منسلک ہوں۔', 'ج. دنیوي چارې دې په عملي ډول د آخرت له بریا سره تړلې وي.'),
          ('d. Social equality and peace and tranquillity should prevail.', 'د۔ معاشرتی مساوات اور امن و سکون کا بول بالا ہو۔', 'د. ټولنیزه برابري او امن و سکون دې غالب وي.'),
          ('e. The conquest of the universe should guide towards the recognition of God.', 'ہ۔ تسخیرِ کائنات معرفتِ الٰہی کی طرف رہنمائی کرے۔', 'ه. د کائنات تسخیر دې د الهي معرفت لوري ته لارښوونه وکړي.'),
          ('f. Power and government should not be an end in themselves, but rather become a means of carrying out the great work of the reform of humanity.', 'و۔ اقتدار و حکومت بجائے خود مقصود نہ ہو بلکہ اصلاحِ انسانیت کے عظیم کام کی انجام دہی کا ذریعہ بنے۔', 'و. واک او حکومت دې پخپله موخه نه وي، بلکې د انسانیت د اصلاح د ستر کار د سرته رسولو وسیله شي.')])
    BOOK.save(98, [(4, r1), (4, rec(t, 4, 187, 98, [187]))], issues=[{'id': 'iski12-pdf098', 'unit': 4, 'printedPage': 186,
               'description': 'p.186 opens Chapter 4. Translation of Bani Isra\'il 80 uses old imperatives "نکالیو", "بنائیو" — kept as printed. The Kanz al-\'Ummal hadith is printed as a translation only (no Arabic) — kept as printed.'}])


if __name__ == '__main__':
    p98()
